jwt.verify(token, key, {
  algorithms: ['RS256'],      // pinned, never read from the token
  issuer: 'https://issuer.example.com',
  audience: 'https://api.example.com/orders',
  clockTolerance: 30          // seconds of skew, not minutes
})

// Vulnerable: the token chooses the algorithm and, via kid, the key.
const h = JSON.parse(b64url(token.split('.')[0]))
jwt.verify(token, loadKey(h.kid), { algorithms: [h.alg] })

// Hardened: server-chosen algorithm, kid used only as a lookup into a known set.
const key = KEYRING.get(header.kid)          // Map of kid -> key; miss = reject
if (!key) throw new Error('unknown kid')
jwt.verify(token, key, { algorithms: ['RS256'] })
